-- NEXORA FORGE ACADEMY INSTALL — PART 16/21
-- Curriculum lessons 235-252 of 324

begin;
insert into public.academy_lessons(id,course_id,title,slug,summary,content_html,starter_code,exercise,status,sort_order,estimated_minutes)
select x.id,c.id,x.title,x.slug,x.summary,x.content_html,x.starter_code,x.exercise,x.status,x.sort_order,x.estimated_minutes
from jsonb_to_recordset($lessons$[{"id":"curriculum-324-javascript-19","course_id":"javascript","title":"افزودن و حذف از آرایه","slug":"javascript-beginner-19","summary":"push عنصر را به انتهای آرایه اضافه و pop آخرین عنصر را حذف می‌کند. هر دو آرایه اصلی را تغییر می‌دهند.","content_html":"<h3>هدف درس</h3><p>push عنصر را به انتهای آرایه اضافه و pop آخرین عنصر را حذف می‌کند. هر دو آرایه اصلی را تغییر می‌دهند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const tasks = [\"مطالعه\", \"تمرین\"];\ntasks.push(\"مرور\");\nconst removed = tasks.pop();\nconsole.log(tasks, removed);</code></pre><h3>تمرین عملی</h3><p>سه کار اضافه کن، آخرین کار را حذف و مقدار حذف‌شده را چاپ کن.</p><h3>نکته فنی</h3><p>push و pop آرایه اصلی را تغییر می‌دهند؛ مقدار pop آخرین عنصر حذف‌شده است.</p><h3>معیار موفقیت</h3><p>عنصر جدید به انتها اضافه و مقدار حذف‌شده درست گزارش شود.</p>","starter_code":"const tasks = [\"مطالعه\", \"تمرین\"];\ntasks.push(\"مرور\");\nconst removed = tasks.pop();\nconsole.log(tasks, removed);","exercise":"سه کار اضافه کن، آخرین کار را حذف و مقدار حذف‌شده را چاپ کن.","status":"published","sort_order":19,"estimated_minutes":25},{"id":"curriculum-324-javascript-20","course_id":"javascript","title":"تعریف و فراخوانی تابع","slug":"javascript-beginner-20","summary":"تابع مجموعه‌ای از دستورهای قابل استفاده مجدد است. تعریف تابع آن را اجرا نمی‌کند و برای اجرا باید فراخوانی شود.","content_html":"<h3>هدف درس</h3><p>تابع مجموعه‌ای از دستورهای قابل استفاده مجدد است. تعریف تابع آن را اجرا نمی‌کند و برای اجرا باید فراخوانی شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function showWelcome() {\n  console.log(\"به آکادمی خوش آمدی\");\n}\nshowWelcome();\nshowWelcome();</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که نام آکادمی را چاپ کند و آن را دو بار فراخوانی کن.</p><h3>نکته فنی</h3><p>تعریف تابع و فراخوانی آن دو مرحله جدا هستند؛ تابع تا زمان فراخوانی اجرا نمی‌شود.</p><h3>معیار موفقیت</h3><p>پیام خوش‌آمدگویی در هر دو فراخوانی نمایش داده شود.</p>","starter_code":"function showWelcome() {\n  console.log(\"به آکادمی خوش آمدی\");\n}\nshowWelcome();\nshowWelcome();","exercise":"تابعی بساز که نام آکادمی را چاپ کند و آن را دو بار فراخوانی کن.","status":"published","sort_order":20,"estimated_minutes":25},{"id":"curriculum-324-javascript-21","course_id":"javascript","title":"پارامتر و آرگومان","slug":"javascript-beginner-21","summary":"پارامتر نام ورودی در تعریف تابع و آرگومان مقدار واقعی هنگام فراخوانی است. می‌توان پارامتر مقدار پیش‌فرض داشت.","content_html":"<h3>هدف درس</h3><p>پارامتر نام ورودی در تعریف تابع و آرگومان مقدار واقعی هنگام فراخوانی است. می‌توان پارامتر مقدار پیش‌فرض داشت.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function welcome(name = \"دانش‌آموز\") {\n  console.log(`سلام ${name}`);\n}\nwelcome(\"نورا\");\nwelcome();</code></pre><h3>تمرین عملی</h3><p>تابعی بساز که نام دوره و زبان را بگیرد؛ زبان پیش‌فرض فارسی باشد.</p><h3>نکته فنی</h3><p>پارامتر در تعریف تابع می‌آید و آرگومان هنگام فراخوانی ارسال می‌شود؛ null مقدار پیش‌فرض را فعال نمی‌کند.</p><h3>معیار موفقیت</h3><p>تابع هم با نام ارسال‌شده و هم با مقدار پیش‌فرض پیام درست بسازد.</p>","starter_code":"function welcome(name = \"دانش‌آموز\") {\n  console.log(`سلام ${name}`);\n}\nwelcome(\"نورا\");\nwelcome();","exercise":"تابعی بساز که نام دوره و زبان را بگیرد؛ زبان پیش‌فرض فارسی باشد.","status":"published","sort_order":21,"estimated_minutes":25},{"id":"curriculum-324-javascript-22","course_id":"javascript","title":"بازگرداندن نتیجه با return","slug":"javascript-beginner-22","summary":"return اجرای تابع را پایان می‌دهد و مقدار را به محل فراخوانی برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>return اجرای تابع را پایان می‌دهد و مقدار را به محل فراخوانی برمی‌گرداند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function calculateTotal(price, count) {\n  return price * count;\n}\nconst total = calculateTotal(120, 3);\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>تابعی بنویس که میانگین دو نمره را برگرداند و بیرون تابع چاپ کند.</p><h3>نکته فنی</h3><p>تابعی که return ندارد در پایان undefined برمی‌گرداند؛ کد پس از return در همان مسیر اجرا نمی‌شود.</p><h3>معیار موفقیت</h3><p>میانگین تابع به‌صورت مقدار قابل استفاده در بیرون برگردد.</p>","starter_code":"function calculateTotal(price, count) {\n  return price * count;\n}\nconst total = calculateTotal(120, 3);\nconsole.log(total);","exercise":"تابعی بنویس که میانگین دو نمره را برگرداند و بیرون تابع چاپ کند.","status":"published","sort_order":22,"estimated_minutes":25},{"id":"curriculum-324-javascript-23","course_id":"javascript","title":"محدوده دسترسی متغیرها","slug":"javascript-beginner-23","summary":"متغیرهای let و const در محدوده بلوک خود قابل دسترسی‌اند. متغیر محلی تابع بیرون از تابع دیده نمی‌شود.","content_html":"<h3>هدف درس</h3><p>متغیرهای let و const در محدوده بلوک خود قابل دسترسی‌اند. متغیر محلی تابع بیرون از تابع دیده نمی‌شود.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const academy = \"NEXORA\";\nfunction showCourse() {\n  const course = \"JavaScript\";\n  console.log(academy, course);\n}\nshowCourse();</code></pre><h3>تمرین عملی</h3><p>متغیری داخل تابع و متغیری بیرون آن بساز و دسترسی مجاز و غیرمجاز را بررسی کن.</p><h3>نکته فنی</h3><p>متغیرهای let و const دارای block scope هستند؛ دسترسی خارج از محدوده خطا می‌دهد.</p><h3>معیار موفقیت</h3><p>بتوانی توضیح بدهی چرا academy در تابع قابل دسترسی است اما course بیرون آن نیست.</p>","starter_code":"const academy = \"NEXORA\";\nfunction showCourse() {\n  const course = \"JavaScript\";\n  console.log(academy, course);\n}\nshowCourse();","exercise":"متغیری داخل تابع و متغیری بیرون آن بساز و دسترسی مجاز و غیرمجاز را بررسی کن.","status":"published","sort_order":23,"estimated_minutes":25},{"id":"curriculum-324-javascript-24","course_id":"javascript","title":"رشته قالبی","slug":"javascript-beginner-24","summary":"Template literal با backtick نوشته می‌شود و با ${} مقدار متغیر را در متن قرار می‌دهد.","content_html":"<h3>هدف درس</h3><p>Template literal با backtick نوشته می‌شود و با ${} مقدار متغیر را در متن قرار می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = \"سارا\";\nconst completed = 12;\nconst message = `سلام ${student}؛ ${completed} درس را تمام کرده‌ای.`;\nconsole.log(message);</code></pre><h3>تمرین عملی</h3><p>پیامی شامل نام دانش‌آموز، نام دوره و تعداد درس‌های باقی‌مانده بساز.</p><h3>نکته فنی</h3><p>داخل ${} می‌توان عبارت JavaScript قرار داد؛ backtick امکان متن چندخطی نیز می‌دهد.</p><h3>معیار موفقیت</h3><p>پیام نهایی نام و تعداد درس را بدون چسباندن رشته‌های متعدد نشان دهد.</p>","starter_code":"const student = \"سارا\";\nconst completed = 12;\nconst message = `سلام ${student}؛ ${completed} درس را تمام کرده‌ای.`;\nconsole.log(message);","exercise":"پیامی شامل نام دانش‌آموز، نام دوره و تعداد درس‌های باقی‌مانده بساز.","status":"published","sort_order":24,"estimated_minutes":25},{"id":"curriculum-324-javascript-25","course_id":"javascript","title":"پاک‌سازی و جست‌وجوی رشته","slug":"javascript-beginner-25","summary":"trim، toLowerCase، includes و slice برای پاک‌سازی، جست‌وجو و استخراج بخشی از متن کاربرد دارند.","content_html":"<h3>هدف درس</h3><p>trim، toLowerCase، includes و slice برای پاک‌سازی، جست‌وجو و استخراج بخشی از متن کاربرد دارند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const entered = \"  NEXORA-FORGE  \";\nconst clean = entered.trim().toLowerCase();\nconsole.log(clean.includes(\"forge\"));\nconsole.log(clean.slice(0, 6));</code></pre><h3>تمرین عملی</h3><p>شناسه را پاک‌سازی کن، وجود forge را بررسی و پیشوند آن را جدا کن.</p><h3>نکته فنی</h3><p>slice اندیس پایان را شامل نمی‌کند؛ trim و toLowerCase رشته تازه برمی‌گردانند.</p><h3>معیار موفقیت</h3><p>شناسه بدون فاصله و با حروف کوچک باشد و جست‌وجوی forge نتیجه درست بدهد.</p>","starter_code":"const entered = \"  NEXORA-FORGE  \";\nconst clean = entered.trim().toLowerCase();\nconsole.log(clean.includes(\"forge\"));\nconsole.log(clean.slice(0, 6));","exercise":"شناسه را پاک‌سازی کن، وجود forge را بررسی و پیشوند آن را جدا کن.","status":"published","sort_order":25,"estimated_minutes":25},{"id":"curriculum-324-javascript-26","course_id":"javascript","title":"ساخت شیء و ویژگی‌ها","slug":"javascript-beginner-26","summary":"شیء مجموعه‌ای از ویژگی‌های نام‌دار است و برای نگهداری اطلاعات مرتبط مانند نام و سطح مناسب است.","content_html":"<h3>هدف درس</h3><p>شیء مجموعه‌ای از ویژگی‌های نام‌دار است و برای نگهداری اطلاعات مرتبط مانند نام و سطح مناسب است.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const student = {\n  name: \"سارا\",\n  level: \"beginner\",\n  active: true\n};\nconsole.log(student.name, student.level);</code></pre><h3>تمرین عملی</h3><p>شیئی برای دوره بساز که title، level و lessonCount داشته باشد.</p><h3>نکته فنی</h3><p>ویژگی‌ها با نقطه و براکت قابل دسترسی‌اند؛ ویژگی ناموجود معمولاً undefined است.</p><h3>معیار موفقیت</h3><p>سه ویژگی title، level و lessonCount درست ذخیره و خوانده شوند.</p>","starter_code":"const student = {\n  name: \"سارا\",\n  level: \"beginner\",\n  active: true\n};\nconsole.log(student.name, student.level);","exercise":"شیئی برای دوره بساز که title، level و lessonCount داشته باشد.","status":"published","sort_order":26,"estimated_minutes":25},{"id":"curriculum-324-javascript-27","course_id":"javascript","title":"انتخاب عنصر از DOM","slug":"javascript-beginner-27","summary":"DOM نمای درختی عناصر صفحه است. querySelector نخستین عنصری را که با انتخابگر CSS تطبیق دارد برمی‌گرداند.","content_html":"<h3>هدف درس</h3><p>DOM نمای درختی عناصر صفحه است. querySelector نخستین عنصری را که با انتخابگر CSS تطبیق دارد برمی‌گرداند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const status = document.querySelector(\"#status\");\nconsole.log(status);</code></pre><h3>تمرین عملی</h3><p>در HTML یک عنصر با id مشخص بساز و با querySelector انتخابش کن؛ نبودن عنصر را هم بررسی کن.</p><h3>نکته فنی</h3><p>querySelector نخستین تطبیق را برمی‌گرداند و در صورت نبودن عنصر null می‌دهد.</p><h3>معیار موفقیت</h3><p>عنصر هدف انتخاب شود و نبودن آن باعث دسترسی ناامن به null نشود.</p>","starter_code":"const status = document.querySelector(\"#status\");\nconsole.log(status);","exercise":"در HTML یک عنصر با id مشخص بساز و با querySelector انتخابش کن؛ نبودن عنصر را هم بررسی کن.","status":"published","sort_order":27,"estimated_minutes":25},{"id":"curriculum-324-javascript-28","course_id":"javascript","title":"تغییر متن با textContent","slug":"javascript-beginner-28","summary":"پس از انتخاب عنصر DOM می‌توان متن آن را با textContent تغییر داد. این ویژگی متن را به‌صورت متن ساده قرار می‌دهد.","content_html":"<h3>هدف درس</h3><p>پس از انتخاب عنصر DOM می‌توان متن آن را با textContent تغییر داد. این ویژگی متن را به‌صورت متن ساده قرار می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const message = document.querySelector(\"#message\");\nif (message) {\n  message.textContent = \"پیشرفت ذخیره شد\";\n}</code></pre><h3>تمرین عملی</h3><p>متن پیام وضعیت را تغییر بده و حالت نبودن عنصر را مدیریت کن.</p><h3>نکته فنی</h3><p>textContent متن را به‌عنوان HTML تفسیر نمی‌کند و برای نمایش متن کاربر مناسب‌تر است.</p><h3>معیار موفقیت</h3><p>متن عنصر تغییر کند و رشته واردشده به‌صورت متن عادی باقی بماند.</p>","starter_code":"const message = document.querySelector(\"#message\");\nif (message) {\n  message.textContent = \"پیشرفت ذخیره شد\";\n}","exercise":"متن پیام وضعیت را تغییر بده و حالت نبودن عنصر را مدیریت کن.","status":"published","sort_order":28,"estimated_minutes":25},{"id":"curriculum-324-javascript-29","course_id":"javascript","title":"رویداد کلیک","slug":"javascript-beginner-29","summary":"addEventListener تابعی را به رویدادی مانند click متصل می‌کند تا برنامه به کنش کاربر پاسخ دهد.","content_html":"<h3>هدف درس</h3><p>addEventListener تابعی را به رویدادی مانند click متصل می‌کند تا برنامه به کنش کاربر پاسخ دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const button = document.querySelector(\"#counter-button\");\nlet count = 0;\nbutton?.addEventListener(\"click\", () =&gt; {\n  count++;\n  console.log(count);\n});</code></pre><h3>تمرین عملی</h3><p>دکمه‌ای بساز که با هر کلیک شمارنده را افزایش دهد و مقدار را روی صفحه نشان دهد.</p><h3>نکته فنی</h3><p>شنونده رویداد را یک بار ثبت کن؛ ثبت چندباره می‌تواند باعث اجرای چندباره تابع شود.</p><h3>معیار موفقیت</h3><p>هر کلیک فقط یک واحد به شمارنده اضافه کند.</p>","starter_code":"const button = document.querySelector(\"#counter-button\");\nlet count = 0;\nbutton?.addEventListener(\"click\", () => {\n  count++;\n  console.log(count);\n});","exercise":"دکمه‌ای بساز که با هر کلیک شمارنده را افزایش دهد و مقدار را روی صفحه نشان دهد.","status":"published","sort_order":29,"estimated_minutes":25},{"id":"curriculum-324-javascript-30","course_id":"javascript","title":"خواندن مقدار ورودی","slug":"javascript-beginner-30","summary":"مقدار input از ویژگی value خوانده می‌شود و معمولاً از نوع رشته است؛ حتی اگر input عددی باشد.","content_html":"<h3>هدف درس</h3><p>مقدار input از ویژگی value خوانده می‌شود و معمولاً از نوع رشته است؛ حتی اگر input عددی باشد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const nameInput = document.querySelector(\"#student-name\");\nconst enteredName = nameInput?.value.trim();\nconsole.log(enteredName);</code></pre><h3>تمرین عملی</h3><p>فیلد نام بساز، مقدارش را بخوان و فاصله‌های ابتدا و انتهای آن را حذف کن.</p><h3>نکته فنی</h3><p>value معمولاً رشته است؛ برای محاسبه عددی باید تبدیل و اعتبارسنجی انجام شود.</p><h3>معیار موفقیت</h3><p>فاصله‌های ابتدا و انتهای نام حذف و مقدار درست خوانده شود.</p>","starter_code":"const nameInput = document.querySelector(\"#student-name\");\nconst enteredName = nameInput?.value.trim();\nconsole.log(enteredName);","exercise":"فیلد نام بساز، مقدارش را بخوان و فاصله‌های ابتدا و انتهای آن را حذف کن.","status":"published","sort_order":30,"estimated_minutes":25},{"id":"curriculum-324-javascript-31","course_id":"javascript","title":"مدیریت ارسال فرم","slug":"javascript-beginner-31","summary":"رویداد submit هنگام ارسال فرم رخ می‌دهد. preventDefault از بارگذاری دوباره صفحه در فرم آزمایشی جلوگیری می‌کند.","content_html":"<h3>هدف درس</h3><p>رویداد submit هنگام ارسال فرم رخ می‌دهد. preventDefault از بارگذاری دوباره صفحه در فرم آزمایشی جلوگیری می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const form = document.querySelector(\"#register-form\");\nform?.addEventListener(\"submit\", (event) =&gt; {\n  event.preventDefault();\n  console.log(\"فرم دریافت شد\");\n});</code></pre><h3>تمرین عملی</h3><p>فرمی با نام و شناسه بساز؛ هنگام ارسال، بارگذاری مجدد را متوقف و مقدارها را بررسی کن.</p><h3>نکته فنی</h3><p>preventDefault فقط رفتار پیش‌فرض مرورگر را متوقف می‌کند و داده را خودکار به سرور نمی‌فرستد.</p><h3>معیار موفقیت</h3><p>فرم بدون بارگذاری مجدد مدیریت و مقدار فیلدها خوانده شوند.</p>","starter_code":"const form = document.querySelector(\"#register-form\");\nform?.addEventListener(\"submit\", (event) => {\n  event.preventDefault();\n  console.log(\"فرم دریافت شد\");\n});","exercise":"فرمی با نام و شناسه بساز؛ هنگام ارسال، بارگذاری مجدد را متوقف و مقدارها را بررسی کن.","status":"published","sort_order":31,"estimated_minutes":25},{"id":"curriculum-324-javascript-32","course_id":"javascript","title":"اعتبارسنجی ساده ورودی","slug":"javascript-beginner-32","summary":"اعتبارسنجی سمت مرورگر خطاهای ساده را پیش از ارسال نشان می‌دهد اما جای اعتبارسنجی سرور را نمی‌گیرد.","content_html":"<h3>هدف درس</h3><p>اعتبارسنجی سمت مرورگر خطاهای ساده را پیش از ارسال نشان می‌دهد اما جای اعتبارسنجی سرور را نمی‌گیرد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>function validateName(value) {\n  const name = value.trim();\n  return name.length &gt;= 2;\n}\nconsole.log(validateName(\"علی\"));\nconsole.log(validateName(\" \"));</code></pre><h3>تمرین عملی</h3><p>تابعی بنویس که نام خالی یا کوتاه‌تر از دو نویسه را رد کند.</p><h3>نکته فنی</h3><p>اعتبارسنجی سمت مرورگر قابل دور زدن است؛ سرور باید داده را دوباره بررسی کند.</p><h3>معیار موفقیت</h3><p>نام معتبر true و نام خالی یا کوتاه false برگرداند.</p>","starter_code":"function validateName(value) {\n  const name = value.trim();\n  return name.length >= 2;\n}\nconsole.log(validateName(\"علی\"));\nconsole.log(validateName(\" \"));","exercise":"تابعی بنویس که نام خالی یا کوتاه‌تر از دو نویسه را رد کند.","status":"published","sort_order":32,"estimated_minutes":25},{"id":"curriculum-324-javascript-33","course_id":"javascript","title":"ذخیره داده در localStorage","slug":"javascript-beginner-33","summary":"localStorage داده متنی را بین بارگذاری‌های صفحه نگه می‌دارد. مقدارهای غیرمتنی باید پیش از ذخیره به رشته تبدیل شوند.","content_html":"<h3>هدف درس</h3><p>localStorage داده متنی را بین بارگذاری‌های صفحه نگه می‌دارد. مقدارهای غیرمتنی باید پیش از ذخیره به رشته تبدیل شوند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>localStorage.setItem(\"academy-theme\", \"dark\");\nconst savedTheme = localStorage.getItem(\"academy-theme\");\nconsole.log(savedTheme);</code></pre><h3>تمرین عملی</h3><p>نام نمایشی کاربر را ذخیره کن، صفحه را دوباره بارگذاری و مقدار را بخوان.</p><h3>نکته فنی</h3><p>localStorage فقط رشته ذخیره می‌کند و برای رمز عبور یا داده حساس مناسب نیست.</p><h3>معیار موفقیت</h3><p>مقدار ذخیره‌شده پس از بارگذاری مجدد صفحه قابل بازیابی باشد.</p>","starter_code":"localStorage.setItem(\"academy-theme\", \"dark\");\nconst savedTheme = localStorage.getItem(\"academy-theme\");\nconsole.log(savedTheme);","exercise":"نام نمایشی کاربر را ذخیره کن، صفحه را دوباره بارگذاری و مقدار را بخوان.","status":"published","sort_order":33,"estimated_minutes":25},{"id":"curriculum-324-javascript-34","course_id":"javascript","title":"تبدیل داده با JSON","slug":"javascript-beginner-34","summary":"JSON قالب متنی تبادل داده است. stringify شیء را به متن و parse متن معتبر را به مقدار JavaScript تبدیل می‌کند.","content_html":"<h3>هدف درس</h3><p>JSON قالب متنی تبادل داده است. stringify شیء را به متن و parse متن معتبر را به مقدار JavaScript تبدیل می‌کند.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const profile = { name: \"سارا\", completed: 8 };\nconst text = JSON.stringify(profile);\nconst restored = JSON.parse(text);\nconsole.log(text, restored.name);</code></pre><h3>تمرین عملی</h3><p>شیء پروفایل را به JSON تبدیل کن، دوباره parse و یکی از ویژگی‌ها را چاپ کن.</p><h3>نکته فنی</h3><p>JSON.parse برای متن نامعتبر خطا می‌دهد؛ در برنامه واقعی آن را با try/catch مدیریت کن.</p><h3>معیار موفقیت</h3><p>شیء بازیابی‌شده ویژگی name و completed را با مقدار اولیه حفظ کند.</p>","starter_code":"const profile = { name: \"سارا\", completed: 8 };\nconst text = JSON.stringify(profile);\nconst restored = JSON.parse(text);\nconsole.log(text, restored.name);","exercise":"شیء پروفایل را به JSON تبدیل کن، دوباره parse و یکی از ویژگی‌ها را چاپ کن.","status":"published","sort_order":34,"estimated_minutes":25},{"id":"curriculum-324-javascript-35","course_id":"javascript","title":"اشکال‌زدایی و breakpoint","slug":"javascript-beginner-35","summary":"breakpoint اجرای برنامه را در یک خط متوقف می‌کند تا بتوانی مقدار متغیرها و مسیر اجرا را در DevTools بررسی کنی.","content_html":"<h3>هدف درس</h3><p>breakpoint اجرای برنامه را در یک خط متوقف می‌کند تا بتوانی مقدار متغیرها و مسیر اجرا را در DevTools بررسی کنی.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const price = 120;\nconst quantity = 3;\nconst total = price * quantity;\nconsole.log(total);</code></pre><h3>تمرین عملی</h3><p>روی خط محاسبه breakpoint بگذار و مقدار price، quantity و total را هنگام توقف ببین.</p><h3>نکته فنی</h3><p>breakpoint را پس از بررسی بردار و پیام‌های آزمایشی غیرضروری را پاک کن.</p><h3>معیار موفقیت</h3><p>بتوانی مقدارهای price، quantity و total را هنگام توقف مشاهده و خطا را ردیابی کنی.</p>","starter_code":"const price = 120;\nconst quantity = 3;\nconst total = price * quantity;\nconsole.log(total);","exercise":"روی خط محاسبه breakpoint بگذار و مقدار price، quantity و total را هنگام توقف ببین.","status":"published","sort_order":35,"estimated_minutes":25},{"id":"curriculum-324-javascript-36","course_id":"javascript","title":"پروژه نهایی: داشبورد پیشرفت","slug":"javascript-beginner-36","summary":"در پروژه پایانی آرایه، شیء، تابع، حلقه، شرط و DOM را ترکیب می‌کنی. برنامه تعداد درس‌های تکمیل‌شده و درصد پیشرفت را محاسبه و نمایش می‌دهد.","content_html":"<h3>هدف درس</h3><p>در پروژه پایانی آرایه، شیء، تابع، حلقه، شرط و DOM را ترکیب می‌کنی. برنامه تعداد درس‌های تکمیل‌شده و درصد پیشرفت را محاسبه و نمایش می‌دهد.</p><h3>نمونه و بررسی</h3><p>کد نمونه را اجرا کن، مقدارها را تغییر بده و تفاوت خروجی را مشاهده کن.</p><pre><code>const lessons = [\n { title: \"متغیرها\", done: true },\n { title: \"شرط‌ها\", done: true },\n { title: \"حلقه‌ها\", done: false },\n { title: \"توابع\", done: false }\n];\nfunction getProgress(items) {\n let completed = 0;\n for (const item of items) if (item.done) completed++;\n const percent = items.length ? Math.round(completed / items.length * 100) : 0;\n return { completed, total: items.length, percent };\n}\nconst report = getProgress(lessons);\nconst output = document.querySelector(\"#progress\");\nif (output) output.textContent = `${report.completed}/${report.total} (${report.percent}%)`;</code></pre><h3>تمرین عملی</h3><p>پروژه را با شش درس توسعه بده و حالت آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده را آزمایش کن؛ دکمه‌ای برای تغییر وضعیت یک درس اضافه کن.</p><h3>نکته فنی</h3><p>آرایه خالی را مدیریت کن تا تقسیم بر صفر رخ ندهد؛ داده، منطق و نمایش را از هم جدا نگه دار.</p><h3>معیار موفقیت</h3><p>داشبورد برای آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده درصد درست از صفر تا صد نشان دهد.</p>","starter_code":"const lessons = [\n { title: \"متغیرها\", done: true },\n { title: \"شرط‌ها\", done: true },\n { title: \"حلقه‌ها\", done: false },\n { title: \"توابع\", done: false }\n];\nfunction getProgress(items) {\n let completed = 0;\n for (const item of items) if (item.done) completed++;\n const percent = items.length ? Math.round(completed / items.length * 100) : 0;\n return { completed, total: items.length, percent };\n}\nconst report = getProgress(lessons);\nconst output = document.querySelector(\"#progress\");\nif (output) output.textContent = `${report.completed}/${report.total} (${report.percent}%)`;","exercise":"پروژه را با شش درس توسعه بده و حالت آرایه خالی، همه تکمیل‌شده و هیچ‌کدام تکمیل‌نشده را آزمایش کن؛ دکمه‌ای برای تغییر وضعیت یک درس اضافه کن.","status":"published","sort_order":36,"estimated_minutes":60}]$lessons$::jsonb) as x(id text,course_id text,title text,slug text,summary text,content_html text,starter_code text,exercise text,status text,sort_order integer,estimated_minutes integer)
join (values
('html','html','beginner'),('html-intermediate','html','intermediate'),('html-advanced','html','advanced'),
('css','css','beginner'),('css-intermediate','css','intermediate'),('css-advanced','css','advanced'),
('javascript','javascript','beginner'),('javascript-intermediate','javascript','intermediate'),('javascript-advanced','javascript','advanced')
) as cp(course_id,language_id,level_id) on cp.course_id=x.course_id
join public.academy_courses c on c.language_id=cp.language_id and c.level_id=cp.level_id
on conflict(id) do update set title=excluded.title,slug=excluded.slug,summary=excluded.summary,content_html=excluded.content_html,starter_code=excluded.starter_code,exercise=excluded.exercise,status='published',sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,archived_at=null,updated_at=now();
commit;
